import fs from 'node:fs';
import vm from 'node:vm';
import assert from 'node:assert/strict';
const file = new URL('../openwrt/dns_benchmark.js',import.meta.url);
assert.ok(fs.existsSync(file),'PE has a dedicated DNS benchmark UI');
let exported;
const context=vm.createContext({baseclass:{extend:x=>(exported=x)},fs:{},ui:{},uci:{},E:()=>{},document:{},window:{}});
vm.runInContext('(function(){'+fs.readFileSync(file,'utf8')+'})()',context);
const candidate={protocol:'doh',id:'google',provider:'Google',dnsServer:'dns.google',successCount:3,totalQueries:4,averageMs:22.5,reliable:false,primaryEligible:true};
const report=exported.normalizeReport({results:[candidate],bootstrapResults:[{id:'google_1',provider:'Google',server:'8.8.8.8',successCount:4,totalQueries:4,averageMs:15,reliable:true}]});
assert.equal(report.results[0].averageMs,22.5);
const metadataMain={protocol:'doh',id:'google',provider:'Google',dnsServer:'dns.google',measured:false,reliable:false,primaryEligible:true};
const metadataBoot={protocol:'udp',id:'google_1',provider:'Google',server:'8.8.8.8',measured:false,reliable:false};
const partialCatalogMain={protocol:'dot',id:'google',provider:'Google',server:'dns.google',primaryEligible:true,automaticEligible:true};
const partialEndpointReport={state:'running',action:'recommend',selectionMode:'two_stage',stage:'endpoints',endpointCoverage:{main:{selected:9,tested:8},bootstrap:{selected:7,tested:7}},results:[partialCatalogMain],bootstrapResults:[metadataBoot],availableResults:[partialCatalogMain],availableBootstrapResults:[metadataBoot]};
assert.doesNotThrow(()=>exported.normalizeReport(partialEndpointReport),'valid partial staged endpoint placeholders must not report malformed measurements');
const partialEndpointNormalized=exported.normalizeReport(partialEndpointReport);
assert.equal(partialEndpointNormalized.results[0].measured,false,'staged endpoint catalogue placeholder is explicitly unmeasured');
assert.equal(partialEndpointNormalized.results[0].dnsServer,'dns.google','pending endpoint server name is normalized without a measurement');
assert.equal(partialEndpointNormalized.results[0].averageMs,undefined,'pending endpoint does not invent latency');
assert.equal(partialEndpointNormalized.availableResults[0].dnsServer,'dns.google','pending manual catalogue uses same endpoint alias');
for(const invalidPartial of [{...partialEndpointReport,state:'done'},{...partialEndpointReport,selectionMode:'all_selected'},{...partialEndpointReport,stage:'pairs'},{...partialEndpointReport,endpointCoverage:null},{...partialEndpointReport,results:[{...partialCatalogMain,successCount:1}]}])
 assert.throws(()=>exported.normalizeReport(invalidPartial),'partial placeholder exception is confined to staged endpoint progress');
const metadataReport=exported.normalizeReport({results:[metadataMain],bootstrapResults:[metadataBoot],pairResults:[]});
assert.equal(metadataReport.results[0].measured,false,'unmeasured catalog metadata is accepted');
assert.equal(metadataReport.results[0].successCount,undefined,'catalog metadata does not invent DNS answers');
assert.equal(metadataReport.bootstrapResults[0].averageMs,undefined,'catalog metadata does not invent latency');
assert.throws(()=>exported.normalizeReport({results:[{...metadataMain,measured:true}],bootstrapResults:[]}),'measured rows still require real counters');
assert.throws(()=>exported.normalizeReport({results:[{...metadataMain,successCount:1}],bootstrapResults:[]}),'partial counters are not silently accepted as metadata');
for(const invalid of [{...candidate,successCount:5},{...candidate,averageMs:-1},{...candidate,protocol:'unknown'},{...candidate,dnsServer:''}]){
 assert.throws(()=>exported.normalizeReport({results:[invalid],bootstrapResults:[]}));
}
assert.throws(()=>exported.normalizeReport({results:Array(257).fill(candidate),bootstrapResults:[]}));
const pair={protocol:'doh',id:'google',dnsServer:'dns.google',bootstrapDnsServer:'8.8.8.8'};
assert.equal(exported.pairMatches(pair,{...pair,success:true}),true);
assert.equal(exported.pairMatches(pair,{...pair,bootstrapDnsServer:'1.1.1.1',success:true}),false);
assert.equal(exported.pairMatches(pair,{...pair,success:false}),false);
assert.equal(exported.pairMatches(pair,{...pair,success:true,httpsTested:false}),false,'DNS-only response cannot grant exact-pair apply proof');
assert.equal(exported.pairMatches({...pair,bootstrapProtocol:'dot'},{...pair,bootstrapProtocol:'udp',success:true}),false,'bootstrap transport binds verification');
assert.equal(exported.normalizeReport({results:[{...candidate,protocol:'tcp'}],bootstrapResults:[],pairResults:[]}).results[0].protocol,'tcp');
assert.throws(()=>exported.normalizeReport({results:[],bootstrapResults:[],pairResults:Array(25).fill({...pair,success:true})}));
assert.throws(()=>exported.normalizeReport({results:[],bootstrapResults:[],pairResults:[{...pair,success:true,stats:{successCount:1,totalQueries:1,averageMs:NaN}}]}));
const workingPair={...pair,bootstrapProtocol:'udp',success:true,stats:{successCount:4,totalQueries:4,averageMs:20}};
assert.equal(exported.normalizeReport({results:[],bootstrapResults:[],pairResults:Array(49).fill(workingPair)}).pairResults.length,49,'49 pairs are accepted without the former 24-pair ceiling');
assert.equal(exported.normalizeReport({results:[],bootstrapResults:[],pairResults:[workingPair],selectionComplete:false,recommendation:{...workingPair,rechecked:true}}).recommendation,null,'partial run never certifies a winner');
assert.equal(exported.normalizeReport({results:[],bootstrapResults:[],pairResults:[workingPair],selectionComplete:true,recommendation:{...workingPair,rechecked:false}}).recommendation,null,'winner must pass repeat verification');
assert.equal(exported.normalizeReport({results:[],bootstrapResults:[],pairResults:[workingPair],selectionComplete:true,recommendation:{...workingPair,rechecked:true}}).recommendation.dnsServer,pair.dnsServer);
assert.equal(exported.normalizeReport({results:[],bootstrapResults:[],pairResults:[workingPair],selectionComplete:true,recommendation:{...workingPair,dnsServer:'unmeasured.example',rechecked:true}}).recommendation,null,'unmeasured tuple cannot become a recommendation');
const fastReport=exported.normalizeReport({results:[],bootstrapResults:[],pairResults:[workingPair],selectionMode:'fast',searchComplete:false,candidatesTotal:49,pairsTested:1,maxPairs:4,budgetSeconds:300,elapsedSeconds:63,selectionComplete:true,recommendation:{...workingPair,rechecked:true}});
assert.equal(fastReport.selectionMode,'fast','bounded search is distinguished from an exhaustive report');
assert.equal(fastReport.searchComplete,false,'a confirmed winner does not mean all candidates were tested');
assert.equal(fastReport.pairsTested,1);
const confirmedSelected={...workingPair,automaticEligible:true,rechecked:true,stats:{...workingPair.stats,reliable:true}};
const secondConfirmedSelected={...confirmedSelected,id:'cloudflare',dnsServer:'cloudflare-dns.com'};
const comparisonOnly={...confirmedSelected,id:'manual',dnsServer:'manual.example',automaticEligible:false,comparisonOnly:true};
const allSelected={results:[],bootstrapResults:[],pairResults:[confirmedSelected,secondConfirmedSelected,comparisonOnly],selectionMode:'all_selected',measurementProfile:'minute_sample',candidatesTotal:63,pairsTested:1,parallelism:2,exhaustiveSelected:false,comparisonComplete:true,selectionComplete:true,recommendation:confirmedSelected};
assert.equal(exported.normalizeReport(allSelected).recommendation,null,'unfinished all-selected comparison has no winner');
assert.equal(exported.normalizeReport({...allSelected,exhaustiveSelected:true}).recommendation,null,'coverage flag alone cannot hide missing pairs');
assert.equal(exported.normalizeReport({...allSelected,pairsTested:63,exhaustiveSelected:true,pairResults:[confirmedSelected,{...secondConfirmedSelected,rechecked:false},comparisonOnly]}).recommendation,null,'two eligible stable confirmations are required');
assert.equal(exported.normalizeReport({...allSelected,pairsTested:63,exhaustiveSelected:true,recommendation:comparisonOnly}).recommendation,null,'comparison-only pair cannot win');
assert.equal(exported.normalizeReport({...allSelected,pairsTested:63,exhaustiveSelected:true,recommendation:{...confirmedSelected,comparisonOnly:true}}).recommendation,null,'comparison-only winner flag is rejected even if eligibility metadata disagrees');
assert.equal(exported.normalizeReport({...allSelected,pairsTested:63,exhaustiveSelected:true,recommendation:{...confirmedSelected,rechecked:false}}).recommendation,null,'complete coverage still requires successful repeat');
assert.equal(exported.normalizeReport({...allSelected,pairsTested:63,exhaustiveSelected:true}).recommendation.dnsServer,workingPair.dnsServer);
const stagedReport={...allSelected,selectionMode:'two_stage',stage:'https',endpointCoverage:{main:{selected:7,tested:7},bootstrap:{selected:9,tested:9}},shortlistLimit:8,shortlistedPairs:8,httpsTestedPairs:8,untestedHttpsPairs:55,pairsTested:8};
assert.equal(exported.normalizeReport(stagedReport).selectionMode,'two_stage','two-stage report is not an exhaustive search');
assert.equal(exported.normalizeReport(stagedReport).recommendation.dnsServer,workingPair.dnsServer,'confirmed finalist can win without exhaustive HTTPS coverage');
assert.equal(exported.normalizeReport({...stagedReport,comparisonComplete:false}).recommendation,null,'unfinished finalist comparison has no winner');
assert.equal(exported.normalizeReport({...stagedReport,pairResults:[{...confirmedSelected,httpsTested:false},secondConfirmedSelected]}).recommendation,null,'DNS-only success cannot enter finalist confirmations');
assert.equal(exported.normalizeReport({...stagedReport,pairResults:[{...confirmedSelected,automaticEligible:undefined},secondConfirmedSelected]}).recommendation,null,'missing eligibility cannot count as a confirmed automatic candidate');
assert.equal(exported.normalizeReport({...stagedReport,recommendation:{...confirmedSelected,automaticEligible:undefined}}).recommendation,null,'winner eligibility must be explicit');
const fullWinner={...confirmedSelected,measurementProfile:'full',httpsTested:true};
const verifiedReport={...stagedReport,state:'done',action:'recommend_verified',recommendationMode:'verified',stage:'complete',phase:'complete',fullVerificationComplete:true,fullVerificationAttempts:1,fullVerificationResults:[fullWinner],recommendation:fullWinner,pairResult:fullWinner};
assert.equal(exported.normalizeReport({...verifiedReport,fullVerificationComplete:false}).recommendation,null,'verified workflow cannot recommend before full stage is complete');
assert.equal(exported.normalizeReport(verifiedReport).recommendation.measurementProfile,'full','verified winner must be the full measured tuple');
assert.equal(exported.normalizeReport(verifiedReport).pairResults.find(r=>r.id===fullWinner.id).measurementProfile,'full','full winner replaces preliminary sampled display row');
const bootstrapProof={success:true,protocol:'udp',server:'9.9.9.9',error:'',checks:[{domain:'dns.google',success:true,reason:''},{domain:'example.com',success:true,reason:''}]};
const reserveWinner={...fullWinner,provider:'Google',bootstrapProvider:'Quad9',bootstrapDnsServer:'9.9.9.9'};
const reserveReport={...verifiedReport,action:'recommend_reserve',reserve:true,excludedProvider:'Cloudflare',currentPrimaryProvider:'Cloudflare',currentBootstrapProvider:'Cloudflare',pairResults:[{...reserveWinner,measurementProfile:'minute_sample'},secondConfirmedSelected],pairResult:reserveWinner,fullVerificationResults:[reserveWinner],recommendation:reserveWinner,bootstrapResults:[{...metadataBoot,server:'9.9.9.9',provider:'Quad9'}],recommendationBootstrapTest:bootstrapProof};
reserveReport.reportId='reserve-report-1';
assert.equal(exported.normalizeReport(reserveReport).reserve,true,'reserve workflow is explicitly distinguished');
assert.equal(exported.normalizeReport(reserveReport).fullVerificationComplete,true,'reserve requires full proof');
assert.equal(exported.normalizeReport({...reserveReport,excludedProvider:'cloudflare',currentPrimaryProvider:'cloudflare',currentBootstrapProvider:'cloudflare',recommendation:{...reserveWinner,mainFamily:'google',bootstrapFamily:'quad9',bootstrapProvider:undefined}}).fullVerificationComplete,true,'backend family IDs prove provider independence without display labels');
assert.equal(exported.normalizeReport({...reserveReport,excludedProvider:'cloudflare',currentPrimaryProvider:'cloudflare',currentBootstrapProvider:'cloudflare',recommendation:{...reserveWinner,mainFamily:'cloudflare',bootstrapFamily:'quad9'}}).recommendation,null,'provider family exclusion cannot be bypassed by display labels');
assert.equal(exported.normalizeReport({...reserveReport,fullVerificationResults:[]}).recommendation,null,'reserve cannot use sample-only proof');
assert.equal(exported.normalizeReport({...reserveReport,recommendationBootstrapTest:{...bootstrapProof,success:false}}).recommendation,null,'reserve requires independently working bootstrap');
assert.equal(exported.normalizeReport({...reserveReport,recommendationBootstrapTest:{...bootstrapProof,server:'1.1.1.1'}}).recommendation,null,'bootstrap proof binds exact endpoint');
for(const invalidVerified of [{...verifiedReport,state:'running'},{...verifiedReport,selectionComplete:false},{...verifiedReport,pairResult:{...fullWinner,success:false}},{...verifiedReport,pairResult:{...fullWinner,dnsServer:'stale.example'}},{...verifiedReport,pairResult:{...fullWinner,rechecked:false}},{...verifiedReport,recommendation:{...fullWinner,stats:{...fullWinner.stats,reliable:false}}},{...verifiedReport,recommendation:{...fullWinner,measurementProfile:'minute_sample'}},{...verifiedReport,fullVerificationResults:[]}])
 assert.equal(exported.normalizeReport(invalidVerified).recommendation,null,'verified workflow rejects incomplete, sample or mismatched full proof');
assert.equal(exported.pairSummary({...workingPair,httpsTested:false}),'DNS отвечает; HTTPS не проверен','DNS-only success is not a full pair pass');
assert.match(exported.pairSummary({success:false,httpsTested:false,error:'dns_query_failed'}),/Ошибки DNS.*HTTPS не проверен/,'DNS failure remains visible before untested HTTPS');
assert.match(exported.pairSummary({success:false,httpsTested:false,error:'child_start_failed'}),/Тест не выполнен.*HTTPS не проверен/,'worker failure is not described as measured DNS');
assert.equal(exported.pairSummary(comparisonOnly),'Только для сравнения','manual/filtering pair is visibly excluded from ranking');
const catalogMain={id:'controld',protocol:'doh',provider:'Control D',dnsServer:'freedns.controld.com/p0',primaryEligible:true,automaticEligible:false};
const catalogBoot={id:'cloudflare_2',protocol:'udp',provider:'Cloudflare',server:'1.0.0.1'};
const catalogReport={results:[candidate],bootstrapResults:report.bootstrapResults,availableResults:[candidate,catalogMain],availableBootstrapResults:[...report.bootstrapResults,catalogBoot]};
assert.equal(exported.normalizeReport(catalogReport).availableResults?.length,2,'full catalog is separate from measured shortlist');
assert.equal(exported.normalizeReport(catalogReport).availableBootstrapResults.length,2);
assert.throws(()=>exported.normalizeReport({...catalogReport,availableResults:[{...catalogMain,protocol:'unknown'}]}),'catalog protocols are validated');
assert.equal(exported.pairSummary({success:false,error:'unsupported_client_routing'}),'Тест не выполнен','infrastructure refusal is not called a bad DNS');
assert.equal(exported.pairSummary({success:false,error:'dns_query_failed'}),'Ошибки DNS');
assert.equal(exported.pairSummary({success:false,error:'service_transport_failed'}),'Сервис недоступен');
assert.match(exported.errorMessage('stability_comparison_incomplete'),/сравнение стабильности не завершено/i,'unfinished clean-run comparison must have a clear explanation');
assert.match(exported.errorMessage('no_fully_verified_pairs'),/полную проверку/i,'all failed full finalists have a truthful readable reason');
assert.doesNotMatch(exported.errorMessage('stale_proof'),/устарело|время|тайм/i,'waiting alone must not be presented as invalidating verified DNS');
assert.doesNotMatch(exported.errorMessage('insufficient_working_pairs'),/быстром тесте/i,'failure does not mislabel all-selected comparison as the retired fast search');
assert.equal(exported.pairSummary({...workingPair,rechecked:false,confirmations:[{success:false,error:'dns_query_failed'}]}),'Повторная проверка не пройдена','unstable finalist is not presented as simply working');
assert.equal(exported.pairSummary({...workingPair,rechecked:false}),'DNS + TLS/HTTP отвечают','initial-only result label stays unchanged without repeat evidence');
for(const code of ['busy','pair_not_verified','verification_expired','configuration_changed','worker_stopped','cancelled','invalid_pair']){
 assert.match(exported.errorMessage(code),/[А-Яа-яЁё]/,code+' readable in Russian');
}
assert.match(exported.errorMessage('unsupported_client_routing'),/IP клиента/,'client-specific routing refusal explains the limitation');
assert.match(exported.errorMessage('active_selection_unavailable'),/выбор прокси/,'actual worker selection error is actionable');
for(const code of ['unsupported_ruleset_routing','rules_cache_unavailable','netstat_unavailable','bootstrap_query_failed'])
 assert.notEqual(exported.errorMessage(code),exported.errorMessage('unknown'),'actionable worker error: '+code);
for(const code of ['dns_apply_helper_unavailable','dns_apply_result_unknown','dns_apply_interrupted_unchanged'])
 assert.notEqual(exported.errorMessage(code),exported.errorMessage('unknown'),'application helper result is translated: '+code);
assert.doesNotMatch(exported.errorMessage('unexpected_apply_error'),/не изменены|сохранены|восстановлены/i,'unknown result must not claim current DNS stayed unchanged');
