// Exercise the actual modal handlers with a minimal DOM, not a second UI implementation.
class Node {
 constructor(tag,attrs,children){this.tag=tag;this.attrs=attrs||{};this.children=[];this.style={};this.disabled=false;this.value='';this.textContent='';this.listeners={};this.append(...(Array.isArray(children)?children:[children]));}
 append(...children){for(const child of children.flat(Infinity))if(child!=null)this.children.push(child);}
 replaceChildren(...children){this.children=[];this.append(...children);}
 appendChild(child){this.insertBefore(child,null);return child;}
 insertBefore(child,before){const old=this.children.indexOf(child);if(old>=0)this.children.splice(old,1);const index=before==null?this.children.length:this.children.indexOf(before);this.children.splice(index,0,child);return child;}
 removeChild(child){this.children.splice(this.children.indexOf(child),1);return child;}
 addEventListener(name,handler){this.listeners[name]=handler;}
 querySelector(){return null;}
 setAttribute(name,value){this.attrs[name]=value;}
 click(){return (this.listeners.click||this.attrs.click)?.({preventDefault(){}});}
}
let modal,pending=false,reloaded=false,failureCommand='',statusFailure=false,status={state:'idle'},nextStatus=status,poll,reservePersisted=null,reserveReadbackMismatch=false;const calls=[],uciWrites=[];
let reserveReady=true,reserveReadyReportId=reserveReport.reportId,reserveSaveError='reserve_recheck_required';
const good={...candidate,successCount:4,reliable:true};
const complete={state:'done',action:'benchmark',results:[good,{...candidate,error:'dns_query_failed'}],bootstrapResults:report.bootstrapResults,progress:100};
const walk=node=>node instanceof Node?[node,...node.children.flatMap(walk)]:[];
const button=label=>walk(modal).find(n=>n.tag==='button'&&n.children.includes(label));
const flush=()=>new Promise(r=>setImmediate(r));
const ctx=vm.createContext({baseclass:{extend:x=>(exported=x)},
 E:(tag,attrs,children)=>new Node(tag,attrs,children),
 document:{getElementById:()=>true,createElement:()=>new Node('style'),head:{appendChild(){}}},
 window:{setTimeout:fn=>{poll=fn;return 1;},clearTimeout(){},location:{reload(){reloaded=true;}}},
 ui:{showModal:(title,children)=>{modal=new Node('modal',{},children)},hideModal:()=>{}},
 uci:{changes:async()=>pending?{podkop:[{}]}:{},unload(){},load:async()=>{},set:(...args)=>uciWrites.push(args)},
 fs:{exec:async(path,args)=>{calls.push(args);const command=args[0];
   if(command===failureCommand)return {code:1,stdout:JSON.stringify({success:false,error:'busy'})};
   if(command==='status'&&statusFailure)return {code:1,stdout:'not-json'};
   if(command==='status')status=nextStatus;
   if(command==='benchmark_start')nextStatus=complete;
   if(command==='recommend_start')nextStatus={...complete,action:'recommend',selectionMode:'fast',searchComplete:false,candidatesTotal:49,pairsTested:1,maxPairs:4,budgetSeconds:300,elapsedSeconds:63,selectionComplete:true,testedSections:['main','GEOBLOCK'],pairResults:[workingPair],recommendation:{...workingPair,rechecked:true}};
   if(command==='recommend_full_start')nextStatus={state:'running',action:'recommend_full',selectionMode:'all_selected'};
   if(command==='recommend_verified_start')nextStatus={...complete,...stagedReport,state:'running',action:'recommend_verified',phase:'full_verify',stage:'full_verify',selectionComplete:false,recommendation:null,pairResult:null,fullVerificationComplete:false,fullVerificationAttempts:1,fullVerificationResults:[{...secondConfirmedSelected,success:false,measurementProfile:'full',httpsTested:false,error:'dns_query_failed'}]};
   if(command==='recommend_reserve_start')nextStatus={...complete,...reserveReport,results:[good]};
   if(command==='reserve_save_start'){
     reservePersisted={dnsType:args[1],dnsServer:args[3],bootstrapDnsType:args[5],bootstrapDnsServer:args[4],enabled:true,autoFailoverEnabled:false,activeSlot:'primary'};
     nextStatus={state:'done',action:'reserve_save'};
   }
   if(command==='reserve_status')return {code:0,stdout:JSON.stringify({success:true,reserve:reserveReadbackMismatch?{...reservePersisted,dnsServer:'different.example'}:reservePersisted,saveReady:reserveReady,saveError:reserveReady?null:reserveSaveError,saveReportId:reserveReadyReportId})};
   if(command==='bootstrap_test_start')nextStatus={...complete,action:'bootstrap_test',bootstrapTest:{...bootstrapProof,success:false,error:'bootstrap_query_failed',checks:[{domain:'dns.google',success:false,reason:'timeout'},{domain:'example.com',success:true,reason:''}]}};
   if(command==='pairs_start')nextStatus={...complete,action:'pairs',pairResults:[{...pair,bootstrapProtocol:'udp',success:true,stats:{successCount:4,totalQueries:4,averageMs:20}}]};
   if(command==='pair_test_start')nextStatus={...complete,action:'pair_test',pairResult:workingPair};
   if(command==='apply_start')nextStatus={...complete,action:'apply'};
   return {code:0,stdout:JSON.stringify(command==='status'?status:{success:true})};
 }}
});
vm.runInContext('(function(){'+fs.readFileSync(file,'utf8')+'})()',ctx);
exported.renderOpenButton({root:new Node('root')}).click();await flush();
