assert.ok(walk(modal).some(n=>n.children.includes('Отдельно не измерялся')),'metadata rows are labeled unmeasured in the table');
assert.ok(!walk(modal).some(n=>n.children.includes('undefined / undefined')),'catalog metadata is not rendered as fake answer counts');
